<template>
  <main class="wa">
    <div class="wa-filter card">
      <label>考评周次<input type="date" v-model="weekInput" @change="loadWeek"></label>
      <label v-if="context.isManager">组长<select v-model="selectedUser" @change="loadWeek"><option value="">请选择人员</option><option v-for="m in context.members" :key="m.user_id" :value="String(m.user_id)">{{ m.name }} · {{ workshops[m.workshop_code] }} {{ m.floor }}楼</option></select></label>
      <span class="week-caption">{{ weekStart }} 至 {{ weekEnd }}</span>
      <button @click="reload" :disabled="busy" aria-label="刷新">↻</button>
    </div>
    <nav class="wa-tabs" aria-label="工作管理功能">
      <button v-for="t in tabs" :key="t.key" :class="{ active: tab === t.key }" @click="tab=t.key">{{ t.label }}</button>
    </nav>
    <p v-if="loading" role="status">正在加载…</p>
    <div v-else-if="!selectedUser && !['rules','members','overview'].includes(tab)" class="card empty">{{ context.isManager ? '请先在人员设置中添加组长，再选择人员。' : '请联系负责人，将您的账号加入考评人员。' }}</div>
    <template v-else-if="tab === 'work'">
      <div class="wa-summary card"><div><small>本周工作</small><strong>{{ submitted.length }} <em>条已提交</em></strong></div><div><small>草稿</small><strong>{{ drafts.length }}</strong></div><div><small>周考评</small><strong class="status-text">{{ statusLabel }}</strong></div></div>
      <div v-if="state.coverage" class="card coverage"><b>日常履职填报情况</b><span>有填报 {{state.coverage.reportedDays}} 天</span><span>已填事项 {{state.coverage.completedItems}} 项</span><span>缺必传照片 {{state.coverage.missingEvidenceItems}} 项</span><span>应填事项：待排班确认</span><small>{{state.coverage.expectedItemsReason}}；有填报一天不代表当天职责已完整履行。</small></div>
      <p v-if="state.report?.feedback" class="feedback">复核意见：{{ state.report.feedback }}</p>
      <div class="card" v-if="!state.config?.length">本周尚未设置评分标准，可先填写工作记录；配置标准后由负责人按周评定。</div>
      <section class="card duty-browser"><div class="section-heading"><div><h2>填报事项</h2><p>先选工作事项，再打开对应工作内容，选择结果并提交验证材料。</p></div><span>{{ weekStart }} 至 {{ weekEnd }}</span></div>
        <nav class="category-tabs" aria-label="工作事项分区"><button v-for="category in dutyCategories" :key="category.name" :class="{active:activeCategory===category.name}" @click="activeCategory=category.name">{{category.name}}<small>{{category.duties.length}} 项</small></button></nav>
        <div class="category-task-list"><article v-for="duty in categoryDuties" :key="duty.id" class="category-task"><div class="category-task-copy"><div class="row"><h3>{{duty.title}}</h3><span class="badge">{{duty.frequency}}</span></div><p>验证事项：{{duty.evidence}}</p><div class="task-result"><span :class="['result-dot',dutyResult(duty).tone]"></span>{{dutyResult(duty).label}}</div></div><button v-if="own && editable" class="primary" @click="openDuty(duty)">{{dutyAction(duty)}}</button><button v-else-if="currentDutyRecord(duty)" @click="openRecord(currentDutyRecord(duty),duty.id)">查看填报</button><span v-else class="no-record">暂无填报</span></article></div>
      </section>
      <section class="card special-records"><div class="section-heading"><div><h2>专项记录</h2><p>工艺测量、专项检查和曲坯分析按实际发生时填报。</p></div></div><div class="special-record-grid"><article v-for="(label,kind) in specialKinds" :key="kind"><div><b>{{label}}</b><small>本周已提交 {{ submitted.filter(r=>r.kind===kind).length }} 条</small></div><button v-if="own && editable" class="primary" @click="openNew(kind)">填写记录</button></article></div></section>
      <section class="card" v-if="state.config?.length"><h2>本周要求</h2><div v-for="r in state.config" :key="r.id" class="requirement"><b>{{ r.title }}</b><span>{{ r.kind === 'manual' ? '负责人复核' : r.kind === 'duties' ? `每日履职 ${r.target} 天` : `提交 ${r.target} 天${kinds[r.kind]}记录` }}</span><p>{{ r.standard }}</p></div></section>
      <section class="card" v-if="drafts.length"><h2>待完成草稿</h2><button class="draft-row" v-for="r in drafts" :key="r.id" @click="openRecord(r)">{{ r.record_date }} · {{ recordLabel(r) }} <span>继续填写 →</span></button></section>
    </template>
    <template v-else-if="tab === 'records'">
      <div class="section-tools"><select v-model="kindFilter" aria-label="记录类型"><option value="">全部类型</option><option v-for="(v,k) in kinds" :value="k">{{v}}</option></select><button v-if="context.isManager && selectedUser" @click="exportWeek" :disabled="busy">导出本周表格</button></div>
      <div class="record-grid"><article v-for="r in filteredRecords" :key="r.id" class="card record"><div class="row"><h2>{{ recordLabel(r) }}</h2><span class="badge">{{ r.status === 'draft' ? '草稿' : '已提交' }}</span></div><p>{{ r.record_date }} · {{ r.payload.floor }}楼</p><p class="record-note">{{ recordSummary(r) }}</p><small>{{ r.photos.length }} 张照片</small><button @click="openRecord(r)">{{ own && editable ? '查看 / 编辑' : '查看详情' }}</button><button v-if="context.isManager && r.status==='submitted' && hasProductionAbnormal(r)" @click="exportProductionReport(r)" :disabled="busy">导出生产异常表</button></article></div>
      <div v-if="!filteredRecords.length" class="card empty">本周暂无对应记录</div>
    </template>
    <template v-else-if="tab === 'assessment'">
      <div v-if="state.coverage" class="card coverage"><b>评分依据概览</b><span>有填报 {{state.coverage.reportedDays}} 天</span><span>已填事项 {{state.coverage.completedItems}} 项</span><span>缺必传照片 {{state.coverage.missingEvidenceItems}} 项</span><span>应填事项：待排班确认</span><small>{{state.coverage.expectedItemsReason}}。当前自动分只评价填报日数，最终须人工复核。</small></div>
      <section v-if="context.isManager" class="card review-ledger"><div class="section-heading"><div><h2>履职明细</h2><p>{{selectedMemberName}} · 按事项查看本周填报结果和验证材料</p></div><span>{{state.records.filter(r=>r.kind==='duties'&&r.status==='submitted').length}} 条填报</span></div>
        <div class="ledger-table-wrap"><table class="ledger-table"><thead><tr><th>人员</th><th>日期</th><th>工作事项</th><th>工作内容</th><th>频次</th><th>输出依据</th><th>选择结果</th><th>验证情况</th><th>验证材料</th></tr></thead><tbody><tr v-for="row in dutyReviewRows" :key="row.key"><td data-label="人员">{{row.name}}</td><td data-label="日期">{{row.date}}</td><td data-label="工作事项">{{row.category}}</td><td data-label="工作内容">{{row.title}}</td><td data-label="频次"><span class="badge">{{row.frequency}}</span></td><td data-label="输出依据">{{row.evidence}}</td><td data-label="选择结果"><b>{{row.status||'未选择'}}</b></td><td data-label="验证情况" class="ledger-note">{{[row.note,row.action,row.reference].filter(Boolean).join('；')||'—'}}</td><td data-label="验证材料"><div v-if="row.photos.length" class="ledger-photos"><WorkPhoto v-for="photo in row.photos" :key="photo.id" :id="photo.id"/></div><span v-else>—</span></td></tr><tr v-if="!dutyReviewRows.length"><td colspan="9" class="ledger-empty">本周暂无日常履职填报</td></tr></tbody></table></div>
      </section>
      <section v-if="canReview && state.config?.length && state.report?.status!=='published'" class="card ai-assist"><div><h2>岗位任职职责评分智能体</h2><p>根据评分标准和已提交的记录生成建议分及理由。照片会列为待核对材料，班长需查看照片后确认最终分数。</p></div><button class="primary" :disabled="busy" @click="suggestAssessment">{{busy?'正在生成…':'生成建议分与理由'}}</button><p v-if="aiNotice" role="status" class="ai-notice">{{aiNotice}}</p><div v-if="aiSuggestion?.suggestions?.length" class="ai-suggestions"><div v-for="suggestion in aiSuggestion.suggestions" :key="suggestion.ruleId"><b>{{suggestion.title}} · 建议 {{suggestion.score}} 分</b><p>{{suggestion.reason}}</p><small v-if="suggestion.evidenceRecordIds.length">关联记录：{{suggestion.evidenceRecordIds.join('、')}}</small></div></div></section>
      <div class="card score-head"><div><small>{{ statusLabel }}</small><strong>{{ canReview && state.report?.status!=='published' ? (reviewTotal ?? '—') : (state.evaluation?.total ?? '—') }}<em> / 100</em></strong></div><p>{{ state.report?.status === 'published' ? '已由负责人复核发布' : '当前为建议与预评分，班长核对后发布最终成绩' }}</p></div>
      <section v-for="r in state.evaluation?.items || []" :key="r.id" class="card score-item"><div class="row"><h2>{{ r.title }}</h2><b>{{ canReview && state.report?.status!=='published' ? (manual[r.id]?.score === '' ? '待复核' : manual[r.id]?.score) : (r.score ?? '待复核') }} / {{ r.max }}</b></div><p>{{ r.standard }}</p><p>{{ r.reason }}</p><small v-if="r.evidence?.length">依据记录：{{ r.evidence.join('、') }}</small>
        <div v-if="canReview && state.report?.status !== 'published'" class="manual-fields"><label>班长确认分<input type="number" min="0" :max="r.max" step="0.1" v-model="manual[r.id].score"></label><label>确认或改分理由<textarea v-model="manual[r.id].reason" placeholder="依据记录和现场核对情况说明最终得分" maxlength="2000"></textarea></label></div>
      </section>
      <section class="card"><h2>每日上报汇总</h2><p>每天提交的记录自动归入本周，无需另填周报或提交周考评。草稿不计入已完成天数。</p><div v-for="(label,kind) in kinds" :key="kind" class="member-row"><b>{{label}}</b><span>{{submitted.filter(r=>r.kind===kind).length}} 条 · {{new Set(submitted.filter(r=>r.kind===kind).map(r=>r.record_date)).size}} 天已上报</span></div><p v-if="state.report?.summary">历史周总结：{{state.report.summary}}</p></section>
      <section class="card" v-if="canReview && state.config?.length"><h2>负责人复核</h2><textarea v-model="feedback" rows="3" maxlength="5000" placeholder="复核意见；退回时请说明需补充或修改的内容"></textarea><div class="review-actions"><button :disabled="busy" @click="review('return')">退回补充</button><button v-if="state.report?.status !== 'published'" class="primary" :disabled="busy" @click="review('publish')">确认并发布成绩</button></div></section>
      <section class="card" v-if="state.events?.length"><h2>处理记录</h2><p v-for="(e,i) in state.events" :key="i">{{ e.created_at }} · {{ e.actor }} · {{ eventNames[e.action] || e.action }} <span v-if="e.detail?.feedback">— {{ e.detail.feedback }}</span></p></section>
    </template>
    <template v-else-if="tab === 'rules'">
      <section class="card"><div class="rule-toolbar"><label>车间<select v-model="ruleWorkshop" @change="loadRules"><option v-for="(v,k) in allowedWorkshops" :value="k">{{v}}</option></select></label><label>生效周<input type="date" v-model="effectiveWeek"></label><button @click="loadRules">加载所选周标准</button></div><p>修改会保存为新版本。已发布的考评保留原标准；自动项按提交天数计分，不将工艺异常直接计为履职扣分。</p>
        <article v-for="(r,i) in ruleDraft" :key="i" class="rule-editor"><div class="rule-grid"><label>考评项目<input v-model="r.title" maxlength="100" placeholder="例如：工艺记录落实"></label><label>计分方式<select v-model="r.kind"><option value="manual">人工复核</option><option v-for="(v,k) in kinds" :value="k">{{v}} · 提交天数</option></select></label><label>满分<input type="number" min="1" max="100" v-model.number="r.max"></label><label v-if="r.kind!=='manual'">每周要求天数<input type="number" min="1" max="7" v-model.number="r.target"></label><label v-if="r.kind!=='manual'">每缺一天扣分<input type="number" min="0.1" max="100" step="0.1" v-model.number="r.deduction"></label></div><label>评判标准<textarea v-model="r.standard" maxlength="2000" placeholder="写清职责、完成要求、证据、扣分条件和不适用情形"></textarea></label><button @click="ruleDraft.splice(i,1)">删除项目</button></article>
        <div class="rule-footer"><button @click="addRule">＋ 添加考评项目</button><b>合计 {{ ruleTotal }} / 100 分</b><button class="primary" :disabled="busy" @click="saveRules">保存新版本</button></div>
      </section><section class="card" v-if="ruleHistory.length"><h2>版本记录</h2><p v-for="r in ruleHistory" :key="r.id">版本 {{r.id}} · {{r.effective_week}} 起生效 · 保存于 {{r.created_at}}</p></section>
    </template>
    <template v-else-if="tab === 'overview'">
      <section class="card"><label>车间<select v-model="overviewWorkshop" @change="loadOverview"><option v-for="(v,k) in allowedWorkshops" :value="k">{{v}}</option></select></label><p>按所选周次汇总本车间人员。只有已发布的成绩才作为正式结果。</p></section>
      <div class="record-grid"><article class="card" v-for="m in overview" :key="m.user_id"><div class="row"><h2>{{m.name}} · {{m.floor}}楼</h2><b>{{m.status==='published'?m.result_json?.total+' 分':'未发布'}}</b></div><p>已提交 {{m.submitted_count}} 条记录 · {{reportLabels[m.status]||'待填报'}}</p><button @click="selectedUser=String(m.user_id);tab='assessment';loadWeek()">查看与复核</button></article></div><div class="card empty" v-if="!overview.length">该车间暂无考评人员</div>
    </template>
    <template v-else-if="tab === 'members'">
      <section class="card"><h2>考评人员设置</h2><p>组长和班长都使用车间人员账号。组长只填报本人；班长可复核制曲车间组长，但不能修改评分标准、人员配置或自己的成绩。</p><div class="rule-grid"><label>组长账号<select v-model="memberForm.userId"><option value="">请选择车间人员账号</option><option v-for="u in staffCandidates" :key="u.id" :value="u.id">{{u.name}}（{{u.id}}）</option></select></label><label>所属车间<input value="制曲车间" disabled></label><label>楼层<select v-model.number="memberForm.floor"><option v-for="n in 5" :value="n">{{n}}楼</option></select></label></div><button class="primary" :disabled="busy || !memberForm.userId" @click="saveMember">保存组长</button></section>
      <section class="card"><div v-for="m in context.members" :key="m.user_id" class="member-row"><b>{{m.name}}</b><span>{{workshops[m.workshop_code]}} · {{m.floor}}楼</span><button @click="memberForm={userId:m.user_id,workshop:m.workshop_code,floor:m.floor}">调整楼层</button></div></section>
      <section class="card"><h2>班长复核授权</h2><p>仅授权制曲车间的车间人员账号。班长可查看、生成评分建议、人工复核及导出组长记录；不能改评分标准和成员。</p><div class="rule-grid"><label>班长账号<select v-model="reviewerUserId"><option value="">请选择车间人员账号</option><option v-for="u in staffCandidates.filter(item=>!context.members.some(member=>String(member.user_id)===String(item.id)))" :key="u.id" :value="u.id">{{u.name}}（{{u.id}}）</option></select></label><button class="primary" :disabled="busy || !reviewerUserId" @click="saveReviewer(true)">授权班长</button></div><div v-for="r in reviewers.filter(item=>item.active)" :key="r.user_id" class="member-row"><b>{{r.name}}</b><span>班长 · 制曲车间</span><button :disabled="busy" @click="saveReviewer(false,r.user_id)">撤销复核授权</button></div></section>
    </template>
    <div v-if="editor" class="editor-backdrop"><section class="editor" role="dialog" aria-modal="true" aria-labelledby="work-editor-title"><header><h2 id="work-editor-title">{{form.kind==='duties' ? `${activeDuty?.category || '工作事项'} · ${activeDuty?.title || '工作内容'}` : kinds[form.kind]}}</h2><button aria-label="关闭填报" @click="closeEditor">✕</button></header>
      <div class="editor-body"><div class="form-pair"><label>日期<input type="date" v-model="form.date" :disabled="!canEditRecord || !!form.id"></label><label>楼层<input :value="`${form.floor}楼`" disabled></label></div>
        <template v-if="form.kind==='duties'"><p class="cadence-note">{{ cadenceByKey[form.mode]?.description }} · {{ activeDuty?.category }}</p><article v-if="activeDuty && checkFor(activeDuty.id)" class="duty-entry"><div class="duty-title"><b>{{ activeDuty.title }}</b><span class="badge">{{ activeDuty.frequency }}</span></div><p class="duty-evidence">对应验证事项：{{ activeDuty.evidence }}<strong v-if="activeDuty.photoRequired"> · 本项需上传照片</strong></p><label>本项结果<select v-model="checkFor(activeDuty.id).status" :disabled="!canEditRecord"><option value="">请选择结果</option><option v-for="option in activeDuty.options" :key="option" :value="option">{{ option }}</option></select></label><label>验证情况<textarea v-model="checkFor(activeDuty.id).note" rows="3" maxlength="2000" :disabled="!canEditRecord" :placeholder="activeDuty.abnormalOptions.includes(checkFor(activeDuty.id).status)?'请说明异常情况、发现时间和影响':'填写对应记录或验证情况'"></textarea></label><section v-if="activeDuty.id==='production_progress' && checkFor(activeDuty.id).status==='异常'" class="production-report-fields"><h3>生产异常跟踪表</h3><p>按原跟踪表整理导出；请填写问题分析和改进措施。</p><div class="form-pair"><label>开机时间<input v-model="checkFor(activeDuty.id).productionReport.startTime" :disabled="!canEditRecord" placeholder="如 08:00"></label><label>结束时间<input v-model="checkFor(activeDuty.id).productionReport.endTime" :disabled="!canEditRecord" placeholder="如 16:30"></label></div><div class="form-pair"><label>AGV数量<input v-model="checkFor(activeDuty.id).productionReport.agvCount" :disabled="!canEditRecord" inputmode="numeric"></label><label>下线车号<input v-model="checkFor(activeDuty.id).productionReport.vehicleNo" :disabled="!canEditRecord"></label></div><label>维修进度<textarea v-model="checkFor(activeDuty.id).productionReport.repairProgress" rows="2" :disabled="!canEditRecord"></textarea></label><div v-for="(issue,i) in checkFor(activeDuty.id).productionReport.issues" :key="i" class="production-issue"><div class="form-pair"><label>问题类别<select v-model="issue.category" :disabled="!canEditRecord"><option value="">请选择</option><option>设备</option><option>人员</option><option>其它</option></select></label><label>耽误总时长<input v-model="issue.delay" :disabled="!canEditRecord" placeholder="如 60分钟"></label></div><label>问题描述<textarea v-model="issue.description" rows="2" :disabled="!canEditRecord"></textarea></label><button v-if="canEditRecord && checkFor(activeDuty.id).productionReport.issues.length>1" @click="checkFor(activeDuty.id).productionReport.issues.splice(i,1)">删除问题</button></div><button v-if="canEditRecord" @click="addProductionIssue(checkFor(activeDuty.id))">＋ 添加问题</button><label>改进措施<textarea v-model="checkFor(activeDuty.id).productionReport.measuresText" rows="3" :disabled="!canEditRecord" placeholder="每项措施单独一行"></textarea></label></section><label>处理 / 闭环情况<textarea v-model="checkFor(activeDuty.id).action" rows="2" maxlength="2000" :disabled="!canEditRecord" placeholder="未完成事项说明计划；异常事项填写处理和跟进结果"></textarea></label><label>验证材料链接<input v-model="checkFor(activeDuty.id).reference" maxlength="500" :disabled="!canEditRecord" placeholder="可粘贴问题分析表、反馈记录或 WPS 链接"></label><div class="duty-photos"><div v-for="p in photosFor(activeDuty.id)" :key="p.id"><WorkPhoto :id="p.id"/><button v-if="canEditRecord" @click="removePhoto(p.id)" :disabled="busy">移除</button></div><div v-for="p in pendingFor(activeDuty.id)" :key="p.key" class="pending-photo"><img :src="p.url" alt="待上传照片"><button v-if="canEditRecord" @click="removePending(p.key)">移除待上传照片</button><small>保存时上传</small></div></div><div v-if="canEditRecord && photosFor(activeDuty.id).length+pendingFor(activeDuty.id).length<6" class="photo-actions"><label class="file-button">拍照上传<input type="file" accept="image/jpeg,image/png" capture="environment" @change="uploadPhoto($event,activeDuty.id)" :disabled="busy"></label><label class="file-button">从相册选照片<input type="file" accept="image/jpeg,image/png" @change="uploadPhoto($event,activeDuty.id)" :disabled="busy"></label><small v-if="!form.id">照片先暂存，保存时自动上传</small></div></article><p v-if="missingDutyPhotos.length" class="photo-warning">本项需上传照片后才能提交。</p></template>
        <template v-if="form.kind==='process'"><h3>曲块厚度（cm）</h3><p>填写厚度时请完成十个数据；仅测破碎度时可留空。工艺合格范围待负责人确认。</p><div class="measurement-grid"><label v-for="(_,i) in form.thickness" :key="i">数据 {{i+1}}<input type="number" step="0.01" min="0" max="100" inputmode="decimal" v-model="form.thickness[i]" :disabled="!canEditRecord"></label></div><h3>闸距 / 破碎度</h3><div v-for="(line,i) in form.lines" :key="i" class="line-fields"><b>{{i+1}}线</b><label>闸距（含单位）<input v-model="line.gap" maxlength="40" :disabled="!canEditRecord" placeholder="例如：6 / 7"></label><label>破碎度（%）<input type="number" inputmode="decimal" step="0.01" min="0" max="100" v-model="line.crushing" :disabled="!canEditRecord"></label></div></template>
        <template v-if="form.kind==='inspection'"><label>专项主题<input v-model="form.theme" maxlength="150" :disabled="!canEditRecord" placeholder="例如：设备安全防护检查"></label><label class="check-line"><input type="checkbox" v-model="form.noIssue" :disabled="!canEditRecord">已检查，未发现问题</label><label>检查 / 问题位置<input v-model="form.location" maxlength="150" :disabled="!canEditRecord"></label></template>
        <label>{{form.kind==='block'?'曲坯分析说明':form.kind==='inspection'?'问题描述 / 检查说明':'测量说明'}}<textarea v-model="form.note" rows="5" maxlength="2000" :disabled="!canEditRecord" :placeholder="form.kind==='block'?'记录厚度、颜色、水分感受、破碎情况及异常':'填写现场情况和依据'"></textarea></label>
        <label>处理情况 / 后续计划<textarea v-model="form.action" rows="3" maxlength="2000" :disabled="!canEditRecord"></textarea></label>
        <template v-if="form.kind!=='duties'"><h3>现场照片（{{ form.photos.length+pendingFor(null).length }} / 6）</h3><p>支持直接拍照或从相册选取 JPG、PNG；尚未保存的记录会在保存时自动上传。</p>
        <div class="photo-grid"><div v-for="p in form.photos" :key="p.id"><WorkPhoto :id="p.id"/><button v-if="canEditRecord" @click="removePhoto(p.id)" :disabled="busy">移除</button></div><div v-for="p in pendingFor(null)" :key="p.key" class="pending-photo"><img :src="p.url" alt="待上传照片"><button v-if="canEditRecord" @click="removePending(p.key)">移除待上传照片</button><small>保存时上传</small></div></div>
        <div v-if="canEditRecord && form.photos.length+pendingFor(null).length<6" class="photo-actions"><label class="file-button">拍照上传<input type="file" accept="image/jpeg,image/png" capture="environment" @change="uploadPhoto" :disabled="busy"></label><label class="file-button">从相册选照片<input type="file" accept="image/jpeg,image/png" @change="uploadPhoto" :disabled="busy"></label></div></template>
      </div><footer v-if="canEditRecord"><span v-if="busy">正在保存，请稍候…</span><button :disabled="busy" @click="saveRecord('draft')">保存草稿</button><button class="primary" :disabled="busy || missingDutyPhotos.length>0 || missingDutyResult" @click="saveRecord('submitted')">提交记录</button></footer></section></div>
  </main>
</template>

<script setup>
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { work } from '../api/work'
import WorkPhoto from '../components/WorkPhoto.vue'
import { getUser } from '../auth'
const user = getUser()
const kinds = {duties:'日常履职',process:'工艺分析',inspection:'专项检查',block:'曲坯分析'}
const specialKinds = {process:'工艺分析',inspection:'专项检查',block:'曲坯分析'}
const hints = {process:'记录厚度、闸距与破碎度测量数据',inspection:'记录检查主题、问题位置和现场照片',block:'上传曲坯照片，填写观察与处理情况'}
const cadences = [
  {key:'daily',title:'每日事项',description:'按《周一.xlsx》逐项填写每日状态和验证记录。'},
  {key:'weekly',title:'每周事项',description:'本周完成一次；可上传照片并填写对应记录。'},
  {key:'continuous',title:'持续事项',description:'有情况或需要留痕时随时记录，可多次提交。'},
]
const cadenceByKey = Object.fromEntries(cadences.map(c=>[c.key,c]))
const workshops = {raw_grain:'原粮车间',qu_making:'制曲车间',brewing:'酿酒车间'}
const eventNames = {submitted:'提交周考评',published:'发布成绩',returned:'退回补充',record_created:'新增填报',record_updated:'修改填报',photo_added:'上传照片',photo_removed:'移除照片',ai_suggested:'生成智能评分建议'}
const reportLabels={draft:'待周评',submitted:'待周评',returned:'待补充',published:'已发布'}
const overview=ref([]),overviewWorkshop=ref('qu_making')
const today = () => new Date(Date.now()+8*3600000).toISOString().slice(0,10)
function monday(s) { const d=new Date(s+'T00:00:00Z'); if (!Number.isFinite(d.getTime())) return ''; d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7); return d.toISOString().slice(0,10) }
const weekInput=ref(today()), weekStart=computed(()=>monday(weekInput.value)), weekEnd=computed(()=>{if(!weekStart.value)return '';const d=new Date(weekStart.value+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+6);return d.toISOString().slice(0,10)})
const context=ref({members:[],users:[],isManager:false,canConfigure:false}), selectedUser=ref(''), state=ref({records:[],config:[],events:[]}), tab=ref('work'), busy=ref(false), loading=ref(false), kindFilter=ref('')
const reviewers=ref([]),reviewerUserId=ref(''),staffCandidates=computed(()=>context.value.users.filter(u=>u.role==='viewer'))
const ruleWorkshop=ref('qu_making'), effectiveWeek=ref(today()), ruleDraft=ref([]), ruleHistory=ref([]), memberForm=ref({userId:'',workshop:'qu_making',floor:1})
const editor=ref(false), form=ref({}), baseline=ref(''), feedback=ref(''), manual=ref({}), aiSuggestion=ref(null), aiNotice=ref(''), pendingPhotoFiles=ref([]), activeCategory=ref('基础工作'), activeDutyId=ref('')
const own=computed(()=>String(selectedUser.value)===String(user.id)), editable=computed(()=>!state.value.report || state.value.report.status !== 'published'), canEditRecord=computed(()=>own.value && editable.value)
const submitted=computed(()=>state.value.records.filter(r=>r.status==='submitted')), drafts=computed(()=>state.value.records.filter(r=>r.status==='draft'))
const filteredRecords=computed(()=>state.value.records.filter(r=>!kindFilter.value||r.kind===kindFilter.value))
const dutyCategories=computed(()=>{const groups=new Map();for(const duty of context.value.duties||[]){if(!groups.has(duty.category))groups.set(duty.category,[]);groups.get(duty.category).push(duty)}return [...groups].map(([name,duties])=>({name,duties}))})
const categoryDuties=computed(()=>dutyCategories.value.find(group=>group.name===activeCategory.value)?.duties||[])
const activeDuty=computed(()=>{const id=activeDutyId.value||form.value.checks?.[0]?.dutyId;return context.value.duties?.find(duty=>duty.id===id)||null})
const missingDutyPhotos=computed(()=>form.value.kind==='duties'?(form.value.checks||[]).map(c=>context.value.duties?.find(d=>d.id===c.dutyId)).filter(d=>d?.photoRequired&&!form.value.photos?.some(p=>p.task_key===d.id)&&!pendingPhotoFiles.value.some(p=>p.itemKey===d.id)):[])
const missingDutyResult=computed(()=>form.value.kind==='duties'&&(form.value.checks||[]).some(check=>!check.status))
const canReview=computed(()=>context.value.isManager && !own.value)
const selectedMemberName=computed(()=>context.value.members?.find(member=>String(member.user_id)===String(selectedUser.value))?.name||state.value.member?.name||'—')
const dutyReviewRows=computed(()=>state.value.records.filter(record=>record.kind==='duties'&&record.status==='submitted').flatMap(record=>(record.payload.checks||[]).map(check=>{const duty=context.value.duties?.find(item=>item.id===check.dutyId);if(!duty)return null;return {key:`${record.id}-${duty.id}`,name:selectedMemberName.value,date:record.record_date,category:duty.category,title:duty.title,frequency:duty.frequency,evidence:duty.evidence,status:check.status,note:check.note,action:check.action,reference:check.reference,photos:(record.photos||[]).filter(photo=>photo.task_key===duty.id)}})).filter(Boolean))
const reviewTotal=computed(()=>{const rules=state.value.config||[];if(!rules.length)return null;const scores=rules.map(rule=>Number(manual.value[rule.id]?.score));if(rules.some(rule=>manual.value[rule.id]?.score===''||manual.value[rule.id]?.score==null)||scores.some(score=>!Number.isFinite(score)))return null;return Math.round(scores.reduce((sum,score)=>sum+score,0)*100)/100})
const statusLabel=computed(()=>(reportLabels[state.value.report?.status]||'待周评'))
const allowedWorkshops=computed(()=>({qu_making:workshops.qu_making}))
const tabs=computed(()=>[{key:'work',label:'本周工作'},{key:'records',label:'填报记录'},{key:'assessment',label:'周考评'},...(context.value.isManager?[{key:'overview',label:'车间汇总'}]:[]),...(context.value.canConfigure?[{key:'rules',label:'评分标准'},{key:'members',label:'人员设置'}]:[])])
const ruleTotal=computed(()=>Math.round(ruleDraft.value.reduce((s,r)=>s+(Number(r.max)||0),0)*100)/100)
let loadSequence=0
async function loadWeek(){
  const seq=++loadSequence
  if(!selectedUser.value||!weekStart.value){state.value={records:[],config:[],events:[]};return}
  loading.value=true
  try{const r=await work.get('/week',{params:{userId:selectedUser.value,week:weekStart.value}});if(seq!==loadSequence)return;state.value=r.data;feedback.value='';aiSuggestion.value=null;aiNotice.value='';manual.value=Object.fromEntries((r.data.config||[]).map(rule=>{const item=r.data.evaluation?.items?.find(x=>x.id===rule.id);return [rule.id,{score:rule.kind==='manual'?'':item?.score??'',reason:rule.kind==='manual'?'':item?.reason||''}]}))}finally{if(seq===loadSequence)loading.value=false}
}
async function reload(){const r=await work.get('/context');context.value=r.data;if(!selectedUser.value)selectedUser.value=String(r.data.members.find(m=>String(m.user_id)===String(user.id))?.user_id||r.data.members[0]?.user_id||'');ruleWorkshop.value='qu_making';memberForm.value.workshop='qu_making';await loadWeek();if(context.value.canConfigure){await Promise.all([loadRules(),loadReviewers()])}}
async function run(fn){if(busy.value)return;busy.value=true;try{await fn()}catch{/* API displays the error and retains form input. */}finally{busy.value=false}}
function clearPending(){for(const p of pendingPhotoFiles.value)URL.revokeObjectURL(p.url);pendingPhotoFiles.value=[]}
function selectedDutyDate(){return weekInput.value>=weekStart.value&&weekInput.value<=weekEnd.value?weekInput.value:weekStart.value}
function dutyRecords(duty){return state.value.records.filter(record=>record.kind==='duties'&&record.payload.checks?.some(check=>check.dutyId===duty.id))}
function currentDutyRecord(duty){const records=dutyRecords(duty);if(duty.frequency==='每日')return records.find(record=>record.record_date===selectedDutyDate())||null;if(duty.frequency==='每周')return records.find(record=>record.payload.mode==='weekly')||null;return records.find(record=>record.status==='draft')||records[0]||null}
function dutyResult(duty){const record=currentDutyRecord(duty),check=record?.payload.checks?.find(item=>item.dutyId===duty.id);if(!record)return {label:duty.frequency==='每日'?'待今日填报':duty.frequency==='每周'?'待本周填报':'待记录',tone:'pending'};if(record.status==='draft')return {label:'草稿待提交',tone:'draft'};return {label:check?.status?`结果：${check.status}`:'已提交',tone:'done'}}
function dutyAction(duty){const record=currentDutyRecord(duty);return !record?'填写工作内容':record.status==='draft'?'继续填报':duty.frequency==='持续'?'新增记录':'查看 / 修改'}
function openNew(kind,mode=null,duty=null){clearPending();const base={kind,date:selectedDutyDate(),floor:state.value.member.floor,note:'',theme:'',location:'',noIssue:false,action:'',thickness:Array(10).fill(''),lines:Array.from({length:4},()=>({gap:'',crushing:''})),photos:[]};if(kind==='duties'){base.mode=mode;base.checks=duty?[{dutyId:duty.id,status:'',note:'',action:'',reference:'',...(duty.id==='production_progress'?{productionReport:blankProductionReport()}:{})}]:[]}form.value=base;activeDutyId.value=duty?.id||'';if(duty)activeCategory.value=duty.category;baseline.value=JSON.stringify(form.value);editor.value=true}
function openRecord(r,dutyId=''){clearPending();form.value={...r.payload,id:r.id,revision:r.revision,kind:r.kind,date:r.record_date,checks:(r.payload.checks||[]).map(c=>({...c,productionReport:c.productionReport?{...c.productionReport,issues:(c.productionReport.issues||[]).map(x=>({...x})),measuresText:(c.productionReport.measures||[]).join('\n')}:undefined})),thickness:Array(10).fill('').map((_,i)=>r.payload.thickness?.[i]??''),lines:Array.from({length:4},(_,i)=>({...r.payload.lines?.[i],gap:r.payload.lines?.[i]?.gap||'',crushing:r.payload.lines?.[i]?.crushing??''})),photos:r.photos};activeDutyId.value=dutyId||form.value.checks?.[0]?.dutyId||'';const selected=context.value.duties?.find(duty=>duty.id===activeDutyId.value);if(selected)activeCategory.value=selected.category;baseline.value=JSON.stringify(form.value);editor.value=true}
function openDuty(duty){const existing=currentDutyRecord(duty);if(existing&&!(duty.frequency==='持续'&&existing.status==='submitted')){openRecord(existing,duty.id);return}const mode={每日:'daily',每周:'weekly',持续:'continuous'}[duty.frequency];openNew('duties',mode,duty)}
function checkFor(dutyId){const check=form.value.checks?.find(c=>c.dutyId===dutyId);if(check?.dutyId==='production_progress'&&check.status==='异常'&&!check.productionReport)check.productionReport=blankProductionReport();return check}
function blankProductionReport(){return {startTime:'',endTime:'',agvCount:'',vehicleNo:'',repairProgress:'',issues:[{category:'',description:'',delay:''}],measuresText:'',measures:[]}}
function addProductionIssue(check){check.productionReport.issues.push({category:'',description:'',delay:''})}
function normalizeDutyChecks(){for(const check of form.value.checks||[]){if(check.dutyId==='production_progress'){if(!check.productionReport)check.productionReport=blankProductionReport();check.productionReport.measures=(check.productionReport.measuresText||check.productionReport.measures?.join('\n')||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}}}
function hasProductionAbnormal(record){return record.payload.checks?.some(c=>c.dutyId==='production_progress'&&c.status==='异常'&&c.productionReport)}
function photosFor(dutyId){return (form.value.photos||[]).filter(p=>(p.task_key||null)===(dutyId||null))}
function pendingFor(itemKey){return pendingPhotoFiles.value.filter(p=>(p.itemKey||null)===(itemKey||null))}
function removePending(key){const item=pendingPhotoFiles.value.find(p=>p.key===key);if(item)URL.revokeObjectURL(item.url);pendingPhotoFiles.value=pendingPhotoFiles.value.filter(p=>p.key!==key)}
function recordLabel(r){return r.kind==='duties'?`日常履职 · ${{daily:'每日',weekly:'每周',continuous:'持续'}[r.payload.mode]||''}`:kinds[r.kind]}
function recordSummary(r){if(r.kind==='duties')return (r.payload.checks||[]).map(c=>{const duty=context.value.duties?.find(d=>d.id===c.dutyId);return `${duty?.title||c.dutyId}：${c.status}${c.note?`（${c.note}）`:''}`}).join('；');return r.payload.noIssue?'已检查，未发现问题':r.payload.note||'测量数据记录'}
const dirty=()=>editor.value&&canEditRecord.value&&(JSON.stringify(form.value)!==baseline.value||pendingPhotoFiles.value.length>0)
async function closeEditor(){if(busy.value)return;if(dirty()){try{await ElMessageBox.confirm('有尚未保存的内容，确定放弃吗？','关闭填报',{confirmButtonText:'放弃',cancelButtonText:'继续填写'})}catch{return}}editor.value=false}
async function saveRecord(status){normalizeDutyChecks();await run(async()=>{const queued=[...pendingPhotoFiles.value],initialStatus=queued.length?'draft':status;const r=await work.post('/records',{...form.value,status:initialStatus});Object.assign(form.value,r.data);if(queued.length){for(const photo of queued)await uploadPhotoBlob(photo.blob,photo.itemKey);clearPending();await loadWeek();form.value.photos=state.value.records.find(x=>String(x.id)===String(form.value.id))?.photos||[];if(status==='submitted'&&missingDutyPhotos.value.length){baseline.value=JSON.stringify(form.value);ElMessage.warning(`照片已上传，但仍缺少：${missingDutyPhotos.value.map(x=>x.title).join('、')}`);return}if(status==='submitted'){const submitted=await work.post('/records',{...form.value,status:'submitted'});Object.assign(form.value,submitted.data)}}baseline.value=JSON.stringify(form.value);ElMessage.success(status==='draft'?(queued.length?'草稿已保存，照片已上传':'草稿已保存'):'记录已提交');await loadWeek();if(status==='submitted')editor.value=false})}
async function shrink(file){if(!['image/jpeg','image/png'].includes(file.type))throw new Error('请选择 JPG 或 PNG 照片');if(file.size>25*1024*1024)throw new Error('照片过大，请选择 25MB 以内的图片');const img=await createImageBitmap(file);try{const scale=Math.min(1,1600/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);return await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(new Error('图片处理失败')),'image/jpeg',.85))}finally{img.close()}}
async function uploadPhotoBlob(blob,itemKey=null){const data=new FormData();data.append('photo',blob,'photo.jpg');if(itemKey)data.append('itemKey',itemKey);await work.post(`/records/${form.value.id}/photos`,data)}
async function uploadPhoto(e,itemKey=null){const file=e.target.files?.[0];e.target.value='';if(!file)return;let blob;try{blob=await shrink(file)}catch(err){ElMessage.error(err.message);return}const count=photosFor(itemKey).length+pendingFor(itemKey).length;if(count>=6){ElMessage.warning('每项最多添加 6 张照片');return}if(!form.value.id){pendingPhotoFiles.value=[...pendingPhotoFiles.value,{key:`${Date.now()}-${Math.random()}`,itemKey,blob,url:URL.createObjectURL(blob)}];return}await run(async()=>{await uploadPhotoBlob(blob,itemKey);await loadWeek();form.value.photos=state.value.records.find(r=>String(r.id)===String(form.value.id))?.photos||[];baseline.value=JSON.stringify({...JSON.parse(baseline.value),photos:form.value.photos});ElMessage.success('照片已上传')})}
async function removePhoto(id){await run(async()=>{await work.delete(`/photos/${id}`);form.value.photos=form.value.photos.filter(p=>p.id!==id);baseline.value=JSON.stringify({...JSON.parse(baseline.value),photos:form.value.photos});await loadWeek()})}
async function suggestAssessment(){await run(async()=>{const result=await work.post('/suggest',{userId:selectedUser.value,week:weekStart.value});if(!result.data.available){aiNotice.value=result.data.reason;aiSuggestion.value=null;return}aiSuggestion.value=result.data;for(const item of result.data.suggestions)manual.value[item.ruleId]={score:item.score,reason:item.reason};aiNotice.value='建议分和理由已填入下方，班长可逐项修改后确认发布。';ElMessage.success('评分建议已生成')})}
async function review(action){await run(async()=>{await ElMessageBox.confirm(action==='publish'?'确认工作记录、照片和最终分数无误后发布？':'退回后组长可补充修改本周记录。','复核确认');await work.post('/review',{userId:selectedUser.value,week:weekStart.value,revision:state.value.report?.revision||0,rulesKey:state.value.rulesKey,action,feedback:feedback.value,manual:manual.value,suggestionId:aiSuggestion.value?.suggestionId||null});await loadWeek();ElMessage.success('复核已保存')})}
async function loadRules(){if(!context.value.canConfigure)return;const r=await work.get('/rules',{params:{workshop:ruleWorkshop.value,week:monday(effectiveWeek.value)||weekStart.value}});ruleDraft.value=structuredClone(r.data.current?.rules||[]);ruleHistory.value=r.data.history}
function addRule(){ruleDraft.value.push({title:'',kind:'manual',max:0,standard:'',target:5,deduction:1})}
async function saveRules(){await run(async()=>{await work.post('/rules',{workshop:ruleWorkshop.value,effectiveWeek:effectiveWeek.value,rules:ruleDraft.value});await loadRules();await loadWeek();ElMessage.success('评分标准已保存为新版本')})}
async function saveMember(){await run(async()=>{await work.post('/members',memberForm.value);await reload();ElMessage.success('人员设置已保存')})}
async function loadReviewers(){const r=await work.get('/reviewers',{params:{workshop:'qu_making'}});reviewers.value=r.data}
async function saveReviewer(active,userId=reviewerUserId.value){await run(async()=>{await work.post('/reviewers',{workshop:'qu_making',userId,active});reviewerUserId.value='';await loadReviewers();ElMessage.success(active?'班长复核授权已保存':'班长复核授权已撤销')})}
async function exportWeek(){await run(async()=>{const b=await work.get('/export',{params:{userId:selectedUser.value,week:weekStart.value},responseType:'blob'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`履职记录_${weekStart.value}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)})}
async function exportProductionReport(record){await run(async()=>{const b=await work.get(`/records/${record.id}/production-report`,{responseType:'blob'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`生产异常跟踪表_${record.record_date}.docx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)})}
async function loadOverview(){if(!context.value.isManager||!weekStart.value)return;overviewWorkshop.value=context.value.scope||overviewWorkshop.value;const r=await work.get('/overview',{params:{workshop:overviewWorkshop.value,week:weekStart.value}});overview.value=r.data}
watch([tab,weekStart],()=>{if(tab.value==='overview')loadOverview().catch(()=>{})})
function leave(e){if(dirty()){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(()=>!dirty()||window.confirm('有未保存的填报内容，确定离开吗？'))
onMounted(()=>{reload().catch(()=>{});window.addEventListener('beforeunload',leave)})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',leave))
